import { createHash } from "node:crypto";
import { isAbsolute } from "node:path";

import {
  buildBrainContext,
  isValidBrainPrompt,
  type BrainContextDiagnostic,
  type BrainContextOptions,
  type BrainRecallObservation,
} from "./index.ts";
import { compilerRetrievalLimits, renderDegradedBrainContext } from "./render.ts";
import {
  collaborationKernelRequired,
  recordCollaborationKernelDelivery,
} from "./kernel-receipt.ts";
import type {
  BrainCompilerBudget,
  BrainCompilerCoverage,
  BrainCompilerDiagnostic,
  BrainCompilerOmission,
  BrainCompilerReporting,
  BrainCompilerStop,
  BrainCompiledEvidence,
  BrainProjectResolution,
} from "./retrieve.ts";
import type { CollaborationKernelBudget } from "./kernel.ts";
import type { TemporalQuery } from "./temporal.ts";

export type ContextLifecycle = "session_start" | "resume" | "clear" | "compact" | "prompt";

export type ContextRequest = Readonly<{
  lifecycle: ContextLifecycle;
  cwd: string;
  prompt?: string;
  /** Optional structured temporal query; omitted prompt recalls default to current time in contract 3. */
  temporal?: unknown;
  host: string;
  sessionId?: string;
  reservedBytes: number;
}>;

export type DeliveredEvidenceReceipt = Readonly<{
  id: string;
  provider: string;
  route: string;
  page: string | null;
  source: string | null;
  locator: Record<string, unknown>;
  roles: string[];
  authoredState: string;
  derivedFlags: string[];
  authoritySignals: string[];
  selectionReasons: string[];
  byteCost: number;
  truncated: boolean;
  atomic: boolean;
}>;

export type RecallReceipt = Readonly<{
  snapshotDigest: string | null;
  lifecycle: ContextLifecycle;
  project?: string;
  projectResolution?: BrainProjectResolution;
  temporal?: TemporalQuery;
  selectedEvidence: DeliveredEvidenceReceipt[];
  omissions: BrainCompilerOmission[];
  coverage: BrainCompilerCoverage | null;
  compilerBudget: BrainCompilerBudget | null;
  kernelBudget: CollaborationKernelBudget | null;
  stop: BrainCompilerStop;
  continuation: Record<string, unknown> | null;
  compilerDiagnostics: BrainCompilerDiagnostic[];
  reporting: BrainCompilerReporting | null;
  recallObservation: BrainRecallObservation | null;
  kernel: {
    action: "emitted" | "suppressed";
    reason: string;
    digest: string | null;
    lifecycleGeneration: number | null;
  };
  budget: {
    reservedBytes: number;
    hardBytes: number;
    renderedBytes: number;
  };
}>;

export type ContextEnvelope = Readonly<{
  contractVersion: "anvil-context-envelope/1";
  status: "ready" | "partial" | "empty" | "degraded";
  markdown: string;
  diagnostics: BrainContextDiagnostic[];
  receipt: RecallReceipt;
}>;

export type ContextHarness = Readonly<{
  planContext(request: ContextRequest): Promise<ContextEnvelope>;
}>;

function evidenceReceipt(evidence: BrainCompiledEvidence): DeliveredEvidenceReceipt {
  return {
    id: evidence.id,
    provider: evidence.provider,
    route: evidence.route,
    page: evidence.page,
    source: evidence.source !== null && isAbsolute(evidence.source) ? null : evidence.source,
    locator: { ...evidence.locator },
    roles: [...evidence.roles],
    authoredState: evidence.authoredState,
    derivedFlags: [...evidence.derivedFlags],
    authoritySignals: [...evidence.authoritySignals],
    selectionReasons: [...evidence.selectionReasons],
    byteCost: evidence.byteCost,
    truncated: evidence.truncated,
    atomic: evidence.atomic,
  };
}

const NO_COMPILER_STOP: BrainCompilerStop = {
  reason: "not_run",
  sufficient: true,
  detail: "Prompt compilation was not required for this lifecycle.",
};

type KernelReceiptResult = RecallReceipt["kernel"];

function digestMarkdown(markdown: string): string {
  return createHash("sha256").update(markdown, "utf8").digest("hex");
}

function joinKernelAndPrompt(kernelMarkdown: string, promptMarkdown: string): string {
  return [kernelMarkdown, promptMarkdown].filter(Boolean).join("\n\n");
}

function boundedPromptDiagnostic(
  result: Awaited<ReturnType<typeof buildBrainContext>>,
  request: ContextRequest,
  diagnostic: BrainContextDiagnostic = result.diagnostics[0] ?? {
    code: "BRAIN_CONTEXT_BUDGET_VIOLATION",
    message: "The combined Collaboration Kernel and Prompt Evidence exceed the reviewed delivery allowance.",
    recovery: "Reduce reserved or kernel context before changing the reviewed envelope ceiling.",
  },
): Awaited<ReturnType<typeof buildBrainContext>> {
  const promptHardBytes = result.promptHardBytes ?? result.hardBytes;
  const availableBytes = Math.max(0, promptHardBytes - request.reservedBytes);
  const rendered = renderDegradedBrainContext(diagnostic, undefined, availableBytes, "recall");
  return {
    ...result,
    markdown: rendered.markdown,
    renderedBytes: rendered.renderedBytes,
    hardBytes: promptHardBytes,
    diagnostics: result.diagnostics.length > 0 ? result.diagnostics : [diagnostic],
    deliveredEvidence: [],
  };
}

function fitsPromptEnvelope(
  result: Awaited<ReturnType<typeof buildBrainContext>>,
  request: ContextRequest,
  markdown: string,
): boolean {
  const availableBytes = Math.max(0, result.hardBytes - request.reservedBytes);
  return Buffer.byteLength(markdown, "utf8") <= availableBytes;
}

function envelopeFromResult(
  result: Awaited<ReturnType<typeof buildBrainContext>>,
  request: ContextRequest,
  kernel: KernelReceiptResult,
): ContextEnvelope {
  const compiled = result.compiledContext;
  const kernelProjection = result.kernelProjection;
  const selectedEvidence = (result.deliveredEvidence ?? []).map(evidenceReceipt);
  const status: ContextEnvelope["status"] =
    result.status === "degraded"
      ? "degraded"
      : request.lifecycle === "prompt" && selectedEvidence.length === 0 &&
          result.markdown.length === 0 && compiled?.stop.reason === "no_evidence"
        ? "empty"
        : result.diagnostics.length > 0 ||
            (compiled !== undefined && (!compiled.stop.sufficient || compiled.diagnostics.length > 0 ||
              compilerRetrievalLimits(compiled) !== undefined)) ||
            (kernelProjection !== undefined && kernelProjection.diagnostics.length > 0)
          ? "partial"
          : "ready";
  return {
    contractVersion: "anvil-context-envelope/1",
    status,
    markdown: result.markdown,
    diagnostics: result.diagnostics,
    receipt: {
      snapshotDigest: result.snapshotDigest ?? null,
      lifecycle: request.lifecycle,
      ...(result.matchedProject ? { project: result.matchedProject } : {}),
      ...(result.projectResolution ? { projectResolution: result.projectResolution } : {}),
      ...(compiled?.query.temporal ? { temporal: compiled.query.temporal } : {}),
      selectedEvidence,
      omissions: compiled?.omissions ?? kernelProjection?.omissions ?? [],
      coverage: compiled?.coverage ?? kernelProjection?.coverage ?? null,
      compilerBudget: compiled?.budget ?? null,
      kernelBudget: kernelProjection?.budget ?? null,
      stop: compiled?.stop ?? kernelProjection?.stop ?? NO_COMPILER_STOP,
      continuation: compiled?.continuation ?? kernelProjection?.continuation ?? null,
      compilerDiagnostics: compiled?.diagnostics ?? kernelProjection?.diagnostics ?? [],
      reporting: compiled?.reporting ?? kernelProjection?.reporting ?? null,
      recallObservation: result.recallObservation ?? null,
      kernel,
      budget: {
        reservedBytes: request.reservedBytes,
        hardBytes: result.hardBytes,
        renderedBytes: result.renderedBytes,
      },
    },
  };
}

async function recordKernel(
  request: ContextRequest,
  snapshotDigest: string,
  markdown: string,
  reason: string,
  stateRoot?: string,
): Promise<KernelReceiptResult> {
  const digest = digestMarkdown(markdown);
  if (!request.sessionId || request.host.length === 0) {
    return { action: "emitted", reason, digest, lifecycleGeneration: null };
  }
  const receipt = await recordCollaborationKernelDelivery({
    host: request.host,
    sessionId: request.sessionId,
    snapshotDigest,
    kernelDigest: digest,
    stateRoot,
  });
  return {
    action: "emitted",
    reason,
    digest,
    lifecycleGeneration: receipt.lifecycleGeneration,

 };
}

export function createContextHarness(options: BrainContextOptions = {}): ContextHarness {
  return {
    async planContext(request): Promise<ContextEnvelope> {
      const build = (event: Parameters<typeof buildBrainContext>[0], reservedBytes: number) =>
        buildBrainContext(event, {
          ...options,
          reservedOutputBytes: reservedBytes,
        });

      if (request.lifecycle !== "prompt") {
        const result = await build({ type: "session_start", cwd: request.cwd }, request.reservedBytes);
        const snapshotDigest = result.snapshotDigest;
        const kernel = snapshotDigest && result.status === "ready"
          ? await recordKernel(request, snapshotDigest, result.markdown, request.lifecycle, options.stateRoot)
          : { action: "emitted" as const, reason: request.lifecycle, digest: null, lifecycleGeneration: null };
        return envelopeFromResult(result, request, kernel);
      }

      const promptEvent = {
        type: "user_prompt_submit" as const,
        cwd: request.cwd,
        prompt: request.prompt,
        ...(request.temporal !== undefined ? { temporal: request.temporal } : {}),
      };
      if (!isValidBrainPrompt(request.prompt)) {
        const invalidPrompt = await build(promptEvent, request.reservedBytes);
        return envelopeFromResult(invalidPrompt, request, {
          action: "suppressed", reason: "snapshot_unavailable", digest: null, lifecycleGeneration: null,
        });
      }
      const kernelResult = await build({ type: "session_start", cwd: request.cwd }, 0);
      if (!kernelResult.snapshotDigest) {
        return envelopeFromResult(boundedPromptDiagnostic(kernelResult, request), request, {
          action: "suppressed", reason: "snapshot_unavailable", digest: null, lifecycleGeneration: null,
        });
      }
      if (kernelResult.status === "degraded") {
        return envelopeFromResult(boundedPromptDiagnostic(kernelResult, request), request, {
          action: "suppressed", reason: "kernel_unavailable", digest: null, lifecycleGeneration: null,
        });
      }
      const kernelRequired = await collaborationKernelRequired({
        lifecycle: "prompt",
        host: request.host,
        sessionId: request.sessionId,
        snapshotDigest: kernelResult.snapshotDigest,
        stateRoot: options.stateRoot,
      });
      if (!kernelRequired) {
        const promptResult = await build(promptEvent, request.reservedBytes);
        const normalizedPromptResult = promptResult.status === "degraded" && promptResult.markdown.trim().length === 0
          ? boundedPromptDiagnostic(promptResult, request)
          : promptResult;
        if (normalizedPromptResult.snapshotDigest !== kernelResult.snapshotDigest) {
          const mismatch: BrainContextDiagnostic = {
            code: "BRAIN_SNAPSHOT_INVALID",
            message: "The Brain Snapshot changed while assembling one Context Envelope.",
            recovery: "Retry against one stable validated snapshot.",
          };
          const degraded = { ...normalizedPromptResult, status: "degraded" as const, markdown: "", diagnostics: [mismatch], renderedBytes: 0 };
          return envelopeFromResult(degraded, request, {
            action: "suppressed", reason: "snapshot_changed", digest: null, lifecycleGeneration: null,
          });
        }
        const envelope = envelopeFromResult(normalizedPromptResult, request, {
          action: "suppressed", reason: "retention_receipt_match", digest: null, lifecycleGeneration: null,
        });
        return normalizedPromptResult.status === "degraded" &&
          !normalizedPromptResult.diagnostics.some((item) => item.code === "BRAIN_CONTEXT_BUDGET_VIOLATION")
          ? { ...envelope, status: "partial" }
          : envelope;
      }

      const separatorBytes = kernelResult.markdown.length > 0 ? 2 : 0;
      const promptResult = await build(
        promptEvent,
        request.reservedBytes + Buffer.byteLength(kernelResult.markdown, "utf8") + separatorBytes,
      );
      if (promptResult.snapshotDigest !== kernelResult.snapshotDigest) {
        const mismatch: BrainContextDiagnostic = {
          code: "BRAIN_SNAPSHOT_INVALID",
          message: "The Brain Snapshot changed while assembling one Context Envelope.",
          recovery: "Retry against one stable validated snapshot.",
        };
        const degraded = { ...promptResult, status: "degraded" as const, markdown: "", diagnostics: [mismatch], renderedBytes: 0 };
        return envelopeFromResult(degraded, request, {
          action: "suppressed", reason: "snapshot_changed", digest: null, lifecycleGeneration: null,
        });
      }
      const normalizedPromptResult = promptResult.status === "degraded" && promptResult.markdown.trim().length === 0
        ? boundedPromptDiagnostic(promptResult, request)
        : promptResult;
      const markdown = joinKernelAndPrompt(kernelResult.markdown, normalizedPromptResult.markdown);
      if (!fitsPromptEnvelope(normalizedPromptResult, request, markdown)) {
        const availableBytes = Math.max(0, normalizedPromptResult.hardBytes - request.reservedBytes);
        const kernelBytes = Buffer.byteLength(kernelResult.markdown, "utf8");
        if (normalizedPromptResult.status === "degraded" && kernelBytes <= availableBytes) {
          const kernel = await recordKernel(
            request,
            kernelResult.snapshotDigest,
            kernelResult.markdown,
            "prompt_retrieval_degraded",
            options.stateRoot,
          );
          const combined = {
            ...normalizedPromptResult,
            status: "ready" as const,
            markdown: kernelResult.markdown,
            diagnostics: [...kernelResult.diagnostics, ...normalizedPromptResult.diagnostics],
            renderedBytes: kernelBytes,
            deliveredEvidence: kernelResult.deliveredEvidence ?? [],
            kernelProjection: kernelResult.kernelProjection,
          };
          return { ...envelopeFromResult(combined, request, kernel), status: "partial" };
        }
        const bounded = boundedPromptDiagnostic(
          { ...normalizedPromptResult, status: "degraded" as const },
          request,
        );
        return envelopeFromResult(bounded, request, {
          action: "suppressed", reason: "budget_contract_violation", digest: null, lifecycleGeneration: null,
        });
      }
      const kernel = await recordKernel(
        request,
        kernelResult.snapshotDigest,
        kernelResult.markdown,
        normalizedPromptResult.status === "degraded" ? "prompt_retrieval_degraded" : "retention_unproven",
        options.stateRoot,
      );
      const combined = {
        ...normalizedPromptResult,
        status: normalizedPromptResult.status === "degraded" ? "ready" as const : normalizedPromptResult.status,
        markdown,
        diagnostics: [...kernelResult.diagnostics, ...normalizedPromptResult.diagnostics],
        renderedBytes: Buffer.byteLength(markdown, "utf8"),
        deliveredEvidence: [
          ...(kernelResult.deliveredEvidence ?? []),
          ...(promptResult.deliveredEvidence ?? []),
        ],
        kernelProjection: kernelResult.kernelProjection,
      };
      const envelope = envelopeFromResult(combined, request, kernel);
      return normalizedPromptResult.status === "degraded" && kernelResult.status === "ready"
        ? { ...envelope, status: "partial" }
        : envelope;
    },
  };
}

const defaultHarness = createContextHarness();

export async function planContext(request: ContextRequest): Promise<ContextEnvelope> {
  return defaultHarness.planContext(request);
}

import { resolve } from "node:path";

import { bootstrapSession } from "../bootstrap/index.ts";
import {
  BrainContextError,
  loadBrainBootstrapManifest,
  type BrainContextDiagnosticCode,
} from "./manifest.ts";
import {
  inspectWorkspaceProject,
  selectBrainProject,
  toWorkspaceIdentityInputWithDiagnostics,
} from "./project.ts";
import {
  renderDegradedBrainContext,
  renderPromptEvidenceContext,
  compilerContextDiagnostics,
  compilerRetrievalLimits,
  MAX_RETRIEVAL_LIMIT_SUMMARY,
  type PromptBrainContextRender,
} from "./render.ts";
import {
  retrieveBrainContext,
  type BrainCompiledEvidence,
  type BrainProjectResolution,
  type BrainRetrievalResult,
} from "./retrieve.ts";
import {
  currentTemporalRequestTime,
  normalizeTemporalQuery,
  type TemporalQuery,
  type TemporalQueryInput,
} from "./temporal.ts";
import { resolveBrainSnapshot, type BrainSnapshot } from "./snapshot.ts";
import {
  compileCollaborationKernel,
  type CollaborationKernelProjection,
} from "./kernel.ts";

export type BrainContextEvent =
  | { type: "session_start"; cwd: string }
  | { type: "user_prompt_submit"; cwd: string; prompt: unknown; temporal?: unknown };

export type BrainContextOptions = {
  stateRoot?: string;
  anvilHome?: string;
  agentId?: string;
  env?: Record<string, string | undefined>;
  homeDir?: string;
  retrievalTimeoutMs?: number;
  reservedOutputBytes?: number;
};

export type BrainContextDiagnostic = {
  code: BrainContextDiagnosticCode;
  message: string;
  recovery: string;
};

export type BrainRecallObservation = {
  phase: "disabled" | "guidance_preflight" | "retrieval" | "render";
  timing: {
    total_ms: number;
    retrieval_ms?: number;
  };
  pages: {
    guidance_count: number;
    compiler_evidence_count?: number;
    candidate_count?: number;
    supporting_count?: number;
    selected_count?: number;
    filtered_count?: number;
  };
  bytes: {
    guidance: number;
    guidance_limit: number;
    guidance_headroom: number;
    retrieved_context?: number;
    framing?: number;
    attempted?: number;
    rendered: number;
    payload_limit: number;
    payload_headroom?: number;
  };
  selection_outcome: "not_run" | "unchanged" | "filtered";
  render_outcome: "disabled" | "guidance_rejected" | "within_limit" | "truncated" | "diagnostic";
  diagnostics: BrainContextDiagnosticCode[];
};

export type BrainContextResult = {
  status: "ready" | "degraded";
  markdown: string;
  diagnostics: BrainContextDiagnostic[];
  brainAgentId?: string;
  brainAlias?: string;
  matchedProject?: string;
  projectResolution?: BrainProjectResolution;
  selectedPages?: string[];
  renderedBytes: number;
  hardBytes: number;
  /** Prompt ceiling retained while preparing a Kernel for prompt delivery. */
  promptHardBytes?: number;
  recallObservation?: BrainRecallObservation;
  compiledContext?: BrainRetrievalResult;
  deliveredEvidence?: BrainCompiledEvidence[];
  kernelProjection?: CollaborationKernelProjection;
  snapshotDigest?: string;
};

export type { TemporalQuery, TemporalQueryInput } from "./temporal.ts";

const SESSION_START_QUESTION =
  "Provide the durable identity, collaboration, and current-project orientation required at session start.";
const DEFAULT_SESSION_START_HARD_BYTES = 24_576;
const DEFAULT_PROMPT_RECALL_HARD_BYTES = 16_384;
const MAX_PROMPT_BYTES = 256 * 1024;
const COLLABORATION_KERNEL_FRAMING_RESERVE_BYTES = 1_024;
const COLLABORATION_KERNEL_HARD_BYTES = 4_096;
const COMPILER_RESPONSE_OVERHEAD_BYTES = 16_384;

function diagnosticFromError(error: unknown): BrainContextDiagnostic {
  if (error instanceof BrainContextError) {
    return { code: error.code, message: error.message, recovery: error.recovery };
  }
  return {
    code: "BRAIN_RETRIEVAL_FAILED",
    message: "Brain context assembly failed unexpectedly.",
    recovery: "Run the Anvil Brain doctor and inspect the local runtime configuration.",
  };
}

function matchedProjectFromResolution(resolution: BrainProjectResolution | undefined): string | undefined {
  return resolution?.status === "matched" ? resolution.page : undefined;
}

function degradedResult(
  diagnostic: BrainContextDiagnostic,
  brainRoot?: string,
  renderedHardBytes = DEFAULT_SESSION_START_HARD_BYTES,
  mode: "bootstrap" | "recall" = "bootstrap",
  hardBytes = renderedHardBytes,
): BrainContextResult {
  const rendered = renderDegradedBrainContext(diagnostic, brainRoot, renderedHardBytes, mode);
  return {
    status: "degraded",
    markdown: rendered.markdown,
    diagnostics: [diagnostic],
    renderedBytes: rendered.renderedBytes,
    hardBytes,
  };
}

function availableOutputBytes(hardBytes: number, reservedOutputBytes: number): number {
  return Math.max(0, hardBytes - reservedOutputBytes);
}

export function isValidBrainPrompt(prompt: unknown): prompt is string {
  return typeof prompt === "string" && prompt.trim().length > 0 &&
    !prompt.includes("\0") && Buffer.byteLength(prompt, "utf8") <= MAX_PROMPT_BYTES;
}

function questionForEvent(event: BrainContextEvent): string {
  if (event.type === "session_start") return SESSION_START_QUESTION;
  const prompt = event.prompt;
  if (!isValidBrainPrompt(prompt)) {
    throw new BrainContextError(
      "BRAIN_PROMPT_INVALID",
      "UserPromptSubmit requires a non-empty text prompt within the local retrieval size limit.",
      "Retry with a text prompt no larger than 256 KiB.",
    );
  }
  return prompt;
}

type PromptRecallMeasurement = {
  phase: BrainRecallObservation["phase"];
  guidanceBytes: number;
  guidanceLimit: number;
  guidanceCount: number;
  payloadLimit: number;
  retrievalMs?: number;
  compilerEvidenceCount?: number;
  candidateCount?: number;
  supportingCount?: number;
  selectedCount?: number;
  filteredCount?: number;
  selectionOutcome: BrainRecallObservation["selection_outcome"];
};

function elapsedMilliseconds(startedAt: number): number {
  return Math.max(0, Math.round(performance.now() - startedAt));
}

function recallPages(measurement: PromptRecallMeasurement): BrainRecallObservation["pages"] {
  return {
    guidance_count: measurement.guidanceCount,
    ...(measurement.compilerEvidenceCount !== undefined
      ? { compiler_evidence_count: measurement.compilerEvidenceCount }
      : {}),
    ...(measurement.candidateCount !== undefined ? { candidate_count: measurement.candidateCount } : {}),
    ...(measurement.supportingCount !== undefined ? { supporting_count: measurement.supportingCount } : {}),
    ...(measurement.selectedCount !== undefined ? { selected_count: measurement.selectedCount } : {}),
    ...(measurement.filteredCount !== undefined ? { filtered_count: measurement.filteredCount } : {}),
  };
}

function degradedRecallObservation(
  measurement: PromptRecallMeasurement,
  diagnostic: BrainContextDiagnostic,
  renderedBytes: number,
  totalMs: number,
): BrainRecallObservation {
  return {
    phase: measurement.phase,
    timing: {
      total_ms: totalMs,
      ...(measurement.retrievalMs !== undefined ? { retrieval_ms: measurement.retrievalMs } : {}),
    },
    pages: recallPages(measurement),
    bytes: {
      guidance: measurement.guidanceBytes,
      guidance_limit: measurement.guidanceLimit,
      guidance_headroom: measurement.guidanceLimit - measurement.guidanceBytes,
      rendered: renderedBytes,
      payload_limit: measurement.payloadLimit,
    },
    selection_outcome: measurement.selectionOutcome,
    render_outcome:
      diagnostic.code === "BRAIN_PROMPT_GUIDANCE_TOO_LARGE" ? "guidance_rejected" : "diagnostic",
    diagnostics: [diagnostic.code],
  };
}

function readyRecallObservation(
  measurement: PromptRecallMeasurement,
  rendered: PromptBrainContextRender,
  diagnostics: BrainContextDiagnostic[],
  totalMs: number,
): BrainRecallObservation {
  return {
    phase: "render",
    timing: {
      total_ms: totalMs,
      ...(measurement.retrievalMs !== undefined ? { retrieval_ms: measurement.retrievalMs } : {}),
    },
    pages: recallPages(measurement),
    bytes: {
      guidance: measurement.guidanceBytes,
      guidance_limit: measurement.guidanceLimit,
      guidance_headroom: measurement.guidanceLimit - measurement.guidanceBytes,
      retrieved_cont

ext: rendered.retrievedContextBytes,
      framing: rendered.framingBytes,
      attempted: rendered.attemptedBytes,
      rendered: rendered.renderedBytes,
      payload_limit: measurement.payloadLimit,
      payload_headroom: measurement.payloadLimit - rendered.attemptedBytes,
    },
    selection_outcome: measurement.selectionOutcome,
    render_outcome: rendered.truncated ? "truncated" : "within_limit",
    diagnostics: diagnostics.map((diagnostic) => diagnostic.code),
  };
}

export async function buildBrainContext(
  event: BrainContextEvent,
  options: BrainContextOptions = {},
): Promise<BrainContextResult> {
  const startedAt = performance.now();
  const capturedRequestTime = event.type === "user_prompt_submit" ? currentTemporalRequestTime() : undefined;
  let brainRoot: string | undefined;
  let brainSnapshot: BrainSnapshot | undefined;
  let snapshotDigest: string | undefined;
  let snapshotDiagnostic: BrainContextDiagnostic | undefined;
  let promptRecallMeasurement: PromptRecallMeasurement | undefined;
  const mode = event.type === "session_start" ? "bootstrap" : "recall";
  const reservedOutputBytes = options.reservedOutputBytes ?? 0;
  let totalHardBytes =
    event.type === "session_start" ? DEFAULT_SESSION_START_HARD_BYTES : DEFAULT_PROMPT_RECALL_HARD_BYTES;
  let hardBytes = totalHardBytes;
  let promptHardBytes = DEFAULT_PROMPT_RECALL_HARD_BYTES;

  try {
    if (!Number.isSafeInteger(reservedOutputBytes) || reservedOutputBytes < 0) {
      throw new TypeError("reservedOutputBytes must be a non-negative safe integer.");
    }
    hardBytes = availableOutputBytes(totalHardBytes, reservedOutputBytes);
    const question = questionForEvent(event);
    const cwd = resolve(event.cwd);
    const bootstrap = await bootstrapSession({
      cwd,
      stateRoot: options.stateRoot,
      anvilHome: options.anvilHome,
      agentId: options.agentId,
      env: options.env,
      homeDir: options.homeDir,
      mode: "local_full",
    });

    if (!bootstrap.brain.configured || !bootstrap.brain.agent_id || !bootstrap.brain.brain_root || !bootstrap.brain.wiki_alias) {
      throw new BrainContextError(
        "BRAIN_NOT_CONFIGURED",
        "Anvil Brain configuration is unavailable for this agent runtime.",
        "Run anvil_brain_setup for the configured ANVIL_AGENT_ID.",
      );
    }
    brainRoot = bootstrap.brain.brain_root;
    if (bootstrap.brain.brain_root_status !== "exists") {
      throw new BrainContextError(
        "BRAIN_ROOT_MISSING",
        "The configured Brain root is missing or unusable.",
        "Restore the configured Brain workspace or repair the Anvil Brain config.",
      );
    }

    const snapshot = await resolveBrainSnapshot({
      brainRoot,
      wikiAlias: bootstrap.brain.wiki_alias,
      stateRoot: options.stateRoot,
      env: options.env,
      timeoutMs: options.retrievalTimeoutMs,
    });
    brainRoot = snapshot.wikiRoot;
    brainSnapshot = snapshot;
    snapshotDigest = snapshot.digest;
    if (snapshot.status === "last_known_good") {
      snapshotDiagnostic = {
        code: "BRAIN_SNAPSHOT_STALE",
        message: "Brain delivery is using the validated last-known-good snapshot because current publication failed.",
        recovery: "Repair the current Brain source and publish a new validated snapshot.",
      };
    }

    const manifest = await loadBrainBootstrapManifest(brainRoot);
    if (manifest.version === 1 && event.type === "user_prompt_submit" && event.temporal !== undefined) {
      throw new BrainContextError(
        "BRAIN_RETRIEVAL_INVALID",
        "Temporal queries are only supported by the project-aware contract-3 Brain manifest.",
        "Use a version 2 Brain manifest when supplying a temporal query.",
      );
    }
    const temporal = manifest.version === 2 && event.type === "user_prompt_submit"
      ? normalizeTemporalQuery(event.temporal, capturedRequestTime)
      : undefined;
    promptHardBytes = manifest.budgets.prompt_recall_hard_bytes;
    totalHardBytes =
      event.type === "session_start"
        ? Math.max(
            manifest.budgets.session_start_hard_bytes,
            COLLABORATION_KERNEL_HARD_BYTES + COLLABORATION_KERNEL_FRAMING_RESERVE_BYTES,
          )
        : manifest.budgets.prompt_recall_hard_bytes;
    hardBytes = availableOutputBytes(totalHardBytes, reservedOutputBytes);
    const renderedPromptGuidanceBytes = 0;
    if (event.type === "user_prompt_submit") {
      promptRecallMeasurement = {
        phase: "guidance_preflight",
        guidanceBytes: renderedPromptGuidanceBytes,
        guidanceLimit: manifest.budgets.prompt_guidance_hard_bytes,
        guidanceCount: 0,
        payloadLimit: totalHardBytes,
        selectionOutcome: "not_run",
      };
    }
    const identity = inspectWorkspaceProject(cwd);
    const workspaceIdentityConversion = manifest.version === 2
      ? toWorkspaceIdentityInputWithDiagnostics(identity)
      : undefined;
    const workspaceIdentity = workspaceIdentityConversion?.input;
    const localIdentityDiagnostics: BrainContextDiagnostic[] = workspaceIdentityConversion?.diagnostics.map((diagnostic) => ({
      code: diagnostic.code,
      message: diagnostic.message,
      recovery: diagnostic.recovery,
    })) ?? [];
    let matchedProject: string | undefined;
    if (manifest.version === 1) {
      const selection = selectBrainProject(manifest, identity);
      if (selection.kind === "ambiguous") {
        throw new BrainContextError(
          "BRAIN_PROJECT_AMBIGUOUS",
          `Workspace identity matches multiple Brain project pages: ${selection.pages.join(", ")}.`,
          "Remove duplicate project identifiers from brain-bootstrap.json.",
        );
      }
      matchedProject = selection.kind === "matched" ? selection.project.page : undefined;
    }
    if (event.type === "session_start") {
      if (!manifest.collaboration_kernel || !snapshotDigest || !brainSnapshot) {
        throw new BrainContextError(
          "BRAIN_MANIFEST_INVALID",
          "Brain bootstrap does not declare the reviewed Collaboration Kernel section sources.",
          "Add the approved collaboration_kernel manifest contract before enabling the Context Harness.",
        );
      }
      const kernelProjection = await compileCollaborationKernel({
        brainRoot,
        wikiAlias: bootstrap.brain.wiki_alias,
        snapshot: brainSnapshot,
        manifest: manifest.collaboration_kernel,
        env: options.env,
        timeoutMs: options.retrievalTimeoutMs,
      });
      const rendered = renderPromptEvidenceContext({
        ...(matchedProject ? { matchedProject } : {}),
        evidence: kernelProjection.evidence,
        hardBytes,
      });
      if (rendered.truncated) {
        throw new BrainContextError(
          "BRAIN_CONTEXT_BUDGET_VIOLATION",
          "The exact Collaboration Kernel cannot fit inside the reserved delivery envelope.",
          "Repair the kernel framing allowance; do not truncate mandatory collaboration doctrine.",
        );
      }
      const targetDiagnostic: BrainContextDiagnostic | undefined = kernelProjection.budget.targetExceeded
        ? {
            code: "BRAIN_KERNEL_TARGET_EXCEEDED",
            message: `The Collaboration Kernel uses ${kernelProjection.budget.contentBytes} content bytes, above its 3072-byte target and within its 4096-byte ceiling.`,
            recovery: "Keep the accepted overage visible and reconsider the source sections if the kernel grows.",
          }
        : undefined;
      return {
        status: "ready",
        markdown: rendered.markdown,
        diagnostics: [
          ...(snapshotDiagnostic ? [snapshotDiagnostic] : []),
          ...(targetDiagnostic ? [targetDiagnostic] : []),
        ],
        brainAgentId: bootstrap.brain.agent_id,
        brainAlias: bootstrap.brain.wiki_alias,
        ...(matchedProject ? { matchedProject } : {}),
        selectedPages: kernelProjection.sources.map((source) => source.page),
        renderedBytes: rendered.renderedBytes,
        hardBytes: totalHardBytes,
        deliveredEvidence: kernelProjection.evidence,
        kernelProjection,
        snapshotDigest,
        promptHardBytes,

     };
    }
    const seeds: string[] = [];
    if (promptRecallMeasurement !== undefined) promptRecallMeasurement.phase = "retrieval";
    // The closed compiler profile owns variable evidence and compiler-route
    // costs. Reserve only the local additions it cannot observe, measured by
    // the real renderer rather than a guessed per-response framing constant.
    const emptyProfileBytes = renderPromptEvidenceContext({ evidence: [], includeRoute: true, hardBytes }).attemptedBytes;
    const localProfileBytes = renderPromptEvidenceContext({
      evidence: [], includeRoute: true, hardBytes,
      matchedProject: manifest.version === 1 ? matchedProject : undefined,
      diagnostics: manifest.version === 2 ? localIdentityDiagnostics : [],
      retrievalLimits: MAX_RETRIEVAL_LIMIT_SUMMARY,
      includeRoleDisclaimer: true,
    }).attemptedBytes;
    const compilerDeliveryHardBytes = Math.max(0, hardBytes - Math.max(0, localProfileBytes - emptyProfileBytes));
    const compilerContentHardBytes = compilerDeliveryHardBytes;
    if (compilerContentHardBytes <= 0) {
      throw new BrainContextError(
        "BRAIN_CONTEXT_BUDGET_VIOLATION",
        "Required kernel, framing, diagnostics, and outer context leave no safe allowance for Prompt Evidence.",
        "Reduce reserved or kernel context before changing the reviewed envelope ceiling.",
      );
    }
    const compilerResponseHardBytes = compilerContentHardBytes + COMPILER_RESPONSE_OVERHEAD_BYTES;
    const retrieval = await retrieveBrainContext({
      brainRoot,
      wikiAlias: bootstrap.brain.wiki_alias,
      seeds,
      question,
      targetBytes: Math.min(
        manifest.budgets.prompt_recall_target_bytes,
        Math.max(1, compilerContentHardBytes),
      ),
      hardBytes: compilerResponseHardBytes,
      maxContentBytes: compilerContentHardBytes,
      maxDeliveryBytes: compilerDeliveryHardBytes,
      env: options.env,
      timeoutMs: options.retrievalTimeoutMs,
      compilerContractVersion: manifest.version === 2 ? "3" : "1",
      ...(workspaceIdentity ? { workspaceIdentity } : {}),
      ...(temporal ? { temporal } : {}),
      onRetrievalDuration: (durationMs) => {
        if (promptRecallMeasurement !== undefined) promptRecallMeasurement.retrievalMs = durationMs;
      },
    });
    const projectResolution = manifest.version === 2 ? retrieval.query.projectResolution : undefined;
    const compilerMatchedProject = manifest.version === 2
      ? matchedProjectFromResolution(projectResolution)
      : matchedProject;
    const resolutionDiagnostics = manifest.version === 2
      ? [
          ...localIdentityDiagnostics,
          ...compilerContextDiagnostics(retrieval).filter(
            (diagnostic) => !localIdentityDiagnostics.some((local) => local.code === diagnostic.code),
          ),
        ]
      : [];
    if (
      retrieval.budget.contentBytes !== null &&
      retrieval.budget.contentBytes > compilerContentHardBytes
    ) {
      const diagnostic: BrainContextDiagnostic = {
        code: "BRAIN_CONTEXT_BUDGET_VIOLATION",
        message: "llm-wiki returned evidence content beyond the reserved delivery allowance.",
        recovery: "Repair the compiler content-budget contract; do not truncate the returned evidence in Anvil.",
      };
      return {
        ...degradedResult(diagnostic, undefined, hardBytes, mode, totalHardBytes),
        ...(compilerMatchedProject ? { matchedProject: compilerMatchedProject } : {}),
        ...(projectResolution ? { projectResolution } : {}),
        selectedPages: retrieval.selectedPages,
        compiledContext: retrieval,
        deliveredEvidence: [],
        ...(snapshotDigest ? { snapshotDigest } : {}),
      };
    }

    const projectSet = new Set(
      manifest.version === 1 ? manifest.projects.map((project) => project.page) : [],
    );
    const supportingPaths = manifest.version === 1
      ? retrieval.selectedPages.filter((page) => page !== matchedProject && !projectSet.has(page))
      : retrieval.selectedPages;
    const supportingEvidence = manifest.version === 1
      ? retrieval.evidence.filter((evidence) => {
          if (evidence.page === null) return true;
          return evidence.page !== matchedProject && !projectSet.has(evidence.page);
        })
      : retrieval.evidence;
    if (event.type === "user_prompt_submit") {
      const filteredCount = retrieval.candidateCount - supportingPaths.length;
      promptRecallMeasurement = {
        ...promptRecallMeasurement!,
        phase: "render",
        compilerEvidenceCount: retrieval.evidenceCount,
        candidateCount: retrieval.candidateCount,
        supportingCount: supportingPaths.length,
        selectedCount: supportingPaths.length,
        filteredCount,
        selectionOutcome: filteredCount > 0 ? "filtered" : "unchanged",
      };
      const rendered = renderPromptEvidenceContext({
        ...(compilerMatchedProject ? { matchedProject: compilerMatchedProject } : {}),
        ...(manifest.version === 2 ? { includeRoute: true } : {}),
        ...(retrieval.query.temporal ? { temporal: retrieval.query.temporal } : {}),
        ...(resolutionDiagnostics.length > 0 ? { diagnostics: resolutionDiagnostics } : {}),
        retrievalLimits: compilerRetrievalLimits(retrieval),
        includeRoleDisclaimer: supportingEvidence.length > 0,
        evidence: supportingEvidence,
        hardBytes,
      });
      const diagnostics = [
        ...(snapshotDiagnostic ? [snapshotDiagnostic] : []),
        ...resolutionDiagnostics,
      ];
      if (rendered.truncated) {
        const diagnostic: BrainContextDiagnostic = {
          code: "BRAIN_CONTEXT_BUDGET_VIOLATION",
          message: `The compiled evidence rendered to ${rendered.attemptedBytes} bytes after a ${hardBytes}-byte delivery allowance was reserved.`,
          recovery: "Repair the compiler-to-envelope byte allowance; do not silently truncate compiled evidence.",
        };
        return {
          ...degradedResult(diagnostic, brainRoot, hardBytes, mode, totalHardBytes),
          ...(compilerMatchedProject ? { matchedProject: compilerMatchedProject } : {}),
          ...(projectResolution ? { projectResolution } : {}),
          selectedPages: [
            ...new Set(supportingEvidence.flatMap((evidence) => (evidence.page ? [evidence.page] : []))),
          ],
          compiledContext: retrieval,
          deliveredEvidence: [],
          ...(snapshotDigest ? { snapshotDigest } : {}),
        };
      }
      return {
        status: "ready",
        markdown: rendered.markdown,
        diagnostics,
        brainAgentId: bootstrap.brain.agent_id,
        brainAlias: bootstrap.brain.wiki_alias,
        ...(compilerMatchedProject ? { matchedProject: compilerMatchedProject } : {}),
        ...(projectResolution ? { projectResolution } : {}),
        selectedPages: [
          ...new Set(supportingEvidence.flatMap((evidence) => (evidence.page ? [evidence.page] : []))),
        ],
        renderedBytes: rendered.renderedBytes,
        hardBytes: totalHardBytes,
        compiledContext: retrieval,
        deliveredEvidence: supportingEvidence,
        ...(snapshotDigest ? { snapshotDigest } : {}),
        recallObservation: readyRecallObservation(
          promptRecallMeasurement,
          rendered,
          diagnostics,
          elapsedMilliseconds(startedAt),
        ),
      };
    }

    throw new Error("session_start must return the Collaboration Kernel before prompt retrieval");
  } catch (error) {
    const diagnostic = diagnosticFromError(error);
    const degraded = degradedResult(diagnostic, brainRoot, hardBytes, mode, totalHardBytes);
    if (promptRecallMeasurement === undefined) {
      return { ...degraded, promptHardBytes, ...(snapshotDigest ? { snapshotDigest } : {}) };
    }
    return {
      ...degraded,
      ...(snapshotDigest ? { snapshotDigest } : {}),
      recallObservation: degradedRecallObservation(
        promptRecallMeasurement,
        diagnostic,
        degraded.renderedBytes,
        elapsedMilliseconds(startedAt),
      ),
    };
  }
}

import type { BrainContextDiagnostic } from "./index.ts";
import type { BrainCompiledEvidence, BrainRetrievalResult } from "./retrieve.ts";

export const PROMPT_EVIDENCE_DELIVERY_FORMAT = "anvil_prompt_evidence_v1";

const RETRIEVAL_LIMIT_MESSAGES = {
  unavailable: "Some sources or retrieval providers could not supply evidence; retrieval may be incomplete.",
  problem: "The compiler reported retrieval problems; evidence may be incomplete.",
  budget: "Additional candidate evidence was omitted or shortened to fit the context limit.",
  diagnostics: "Some diagnostic details were not returned; their categories are unavailable here.",
  omissions: "Some omission details were not returned; their reasons are unavailable here.",
} as const;

const EVIDENCE_ROLE_DISCLAIMER =
  "Evidence roles describe retrieval function, not whether this context is sufficient to answer.";

// Local framing, deliberately outside the compiler's closed delivery profile.
// Measure this maximum with the same renderer before assigning its allowance.
export const MAX_RETRIEVAL_LIMIT_SUMMARY = [
  RETRIEVAL_LIMIT_MESSAGES.unavailable,
  RETRIEVAL_LIMIT_MESSAGES.budget,
  RETRIEVAL_LIMIT_MESSAGES.diagnostics,
  RETRIEVAL_LIMIT_MESSAGES.omissions,
].join(" ");

export function compilerHasUnavailableEvidence(diagnostics: BrainRetrievalResult["diagnostics"]): boolean {
  return diagnostics.some(({ code }) =>
    ["SOURCE_PATH_INVALID", "SOURCE_NOT_FOUND", "SOURCE_NOT_TEXT", "PROVIDER_FAILED"].includes(code) ||
    (code.startsWith("LOCI_") &&
      /(?:FAILED|TIMEOUT|UNAVAILABLE|CONFIG_MISSING|NOT_INDEXED|RESULT_INVALID|RESULT_OUT_OF_SCOPE)$/.test(code)),
  );
}

export function compilerRetrievalLimits(retrieval: BrainRetrievalResult): string | undefined {
  const unavailable = compilerHasUnavailableEvidence(retrieval.diagnostics);
  const budgetLimited = retrieval.omissions.some(({ reason }) =>
    ["byte_limit", "content_byte_limit", "delivery_byte_limit", "item_limit"].includes(reason),
  ) || [
    "byte_budget_exhausted", "content_budget_exhausted", "delivery_budget_exhausted", "item_budget_exhausted",
  ].includes(retrieval.stop.reason) || retrieval.evidence.some(({ selectionReasons }) =>
    selectionReasons.some((reason) =>
      ["hard_limit_excerpt", "content_limit_excerpt", "delivered_limit_excerpt"].includes(reason)),
  );
  const messages = [
    ...(unavailable ? [RETRIEVAL_LIMIT_MESSAGES.unavailable]
      : retrieval.stop.reason === "provider_degraded" ? [RETRIEVAL_LIMIT_MESSAGES.problem] : []),
    ...(budgetLimited ? [RETRIEVAL_LIMIT_MESSAGES.budget] : []),
    ...(retrieval.reporting.diagnostics.total > retrieval.reporting.diagnostics.returned
      ? [RETRIEVAL_LIMIT_MESSAGES.diagnostics] : []),
    ...(retrieval.reporting.omissions.total > retrieval.reporting.omissions.returned
      ? [RETRIEVAL_LIMIT_MESSAGES.omissions] : []),
  ];
  return messages.length > 0 ? messages.join(" ") : undefined;
}

/** The compiler's closed delivery-cost profile uses this same projection. */
export function compilerContextDiagnostics(retrieval: BrainRetrievalResult): BrainContextDiagnostic[] {
  const codes = new Set(["PROJECT_IDENTITY_AMBIGUOUS", "PROJECT_IDENTITY_INVALID", "PROJECT_ALIAS_SHADOWED"]);
  const recovery = "Repair the canonical Brain project identity or workspace mapping before relying on project routing.";
  const diagnostics = retrieval.diagnostics
    .filter((diagnostic) => codes.has(diagnostic.code))
    .map((diagnostic) => ({
      code: diagnostic.code as BrainContextDiagnostic["code"],
      message: diagnostic.message,
      recovery,
    }));
  if (retrieval.query.projectResolution?.status === "ambiguous" &&
      !diagnostics.some((diagnostic) => diagnostic.code === "PROJECT_IDENTITY_AMBIGUOUS")) {
    diagnostics.push({
      code: "PROJECT_IDENTITY_AMBIGUOUS",
      message: "llm-wiki reported multiple projects for the observed workspace identity.",
      recovery,
    });
  }
  const temporal = {
    TEMPORAL_HISTORY_INVALID: {
      code: "BRAIN_TEMPORAL_HISTORY_INVALID",
      recovery: "Repair the affected authored history through the wiki Steward; do not use its prose as a settled temporal answer.",
    },
    TEMPORAL_CONFLICT: {
      code: "BRAIN_TEMPORAL_UNCERTAIN",
      recovery: "Use the existing conflict view and inspect the competing claims; do not choose a settled winner from this recall.",
    },
    TEMPORAL_STATE_UNCERTAIN: {
      code: "BRAIN_TEMPORAL_UNCERTAIN",
      recovery: "Use explicit temporal or source follow-up before claiming current or dated applicability; do not invent missing times.",
    },
  } as const;
  for (const diagnostic of retrieval.diagnostics) {
    const mapped = temporal[diagnostic.code as keyof typeof temporal];
    if (mapped) diagnostics.push({ ...mapped, message: diagnostic.message });
  }
  return diagnostics;
}

export function renderCompilerPromptEvidenceContext(retrieval: BrainRetrievalResult): PromptBrainContextRender {
  const resolution = retrieval.contractVersion === "3" ? retrieval.query.projectResolution : undefined;
  return renderPromptEvidenceContext({
    matchedProject: resolution?.status === "matched" ? resolution.page : undefined,
    includeRoute: true,
    diagnostics: retrieval.contractVersion === "3" ? compilerContextDiagnostics(retrieval) : [],
    temporal: retrieval.query.temporal,
    evidence: retrieval.evidence,
    hardBytes: Number.MAX_SAFE_INTEGER,
  });
}

export type PromptEvidenceContextRenderInput = {
  matchedProject?: string;
  includeRoute?: boolean;
  diagnostics?: BrainContextDiagnostic[];
  retrievalLimits?: string;
  includeRoleDisclaimer?: boolean;
  temporal?: BrainRetrievalResult["query"]["temporal"];
  evidence: BrainCompiledEvidence[];
  hardBytes: number;
};

export type BrainContextRender = {
  markdown: string;
  renderedBytes: number;
  truncated: boolean;
};

export type PromptBrainContextRender = BrainContextRender & {
  attemptedBytes: number;
  guidanceBytes: number;
  retrievedContextBytes: number;
  framingBytes: number;
};

export type SessionStartContextRenderInput = {
  continuity: string;
  compactContinuity?: string;
  brain: string;
  hardBytes: number;
};

function evidenceBlock(evidence: BrainCompiledEvidence): string {
  const origin = evidence.page ?? evidence.source ?? evidence.id;
  return [
    `#### \`${origin}\``,
    "",
    evidence.content.trim(),
    "",
    `- evidence_id: \`${evidence.id}\``,
    `- roles: ${evidence.roles.length > 0 ? evidence.roles.map((role) => `\`${role}\``).join(", ") : "none"}`,
  ].join("\n");
}

function section(title: string, body: string): string {
  return [`### ${title}`, "", body].join("\n");
}

function byteLength(value: string): number {
  return Buffer.byteLength(value, "utf8");
}

function truncateUtf8(value: string, maxBytes: number): string {
  if (maxBytes <= 0) return "";
  let bytes = 0;
  let output = "";
  for (const character of value) {
    const characterBytes = byteLength(character);
    if (bytes + characterBytes > maxBytes) break;
    output += character;
    bytes += characterBytes;
  }
  const paragraphBoundary = output.lastIndexOf("\n\n");
  if (paragraphBoundary >= Math.floor(output.length * 0.75)) output = output.slice(0, paragraphBoundary);
  return output.trimEnd();
}

export function renderSessionStartContext(input: SessionStartContextRenderInput): BrainContextRender {
  const continuity = input.continuity.trimEnd();
  const brain = input.brain.trimStart();
  const full = brain.length > 0 ? `${continuity}\n\n${brain}` : continuity;
  if (byteLength(full) <= input.hardBytes) {
    return { markdown: full, renderedBytes: byteLength(full), truncated: false };
  }

  const diagnostic = [
    "## Brain Bootstrap Diagnostic",
    "",
    "- status: degraded",
    "- code: BRAIN_CONTEXT_TRUNCATED",
    "- message: Combined Continuity and Brain context exceeded the reviewed hard byte limit.",
    "- recovery: Reduce the Continuity frame or selected Brain context before raising the reviewed limit.",
  ].join("\n");
  const suffix = `\n\n${diagnostic}`;
  const available = input.hardBytes - byteLength(suffix);
  const fallback = input.compactContinuity?.trimEnd() ?? co

ntinuity;
  const markdown =
    available > 0 ? `${truncateUtf8(fallback, available)}${suffix}` : truncateUtf8(diagnostic, input.hardBytes);
  return { markdown, renderedBytes: byteLength(markdown), truncated: true };
}

export function renderPromptEvidenceContext(input: PromptEvidenceContextRenderInput): PromptBrainContextRender {
  const routeRequested =
    input.includeRoute === true ||
    input.evidence.length > 0;
  const diagnosticSections = input.diagnostics ?? [];
  if (input.evidence.length === 0 && !routeRequested && diagnosticSections.length === 0 &&
      !input.retrievalLimits && !input.includeRoleDisclaimer) {
    return {
      markdown: "",
      renderedBytes: 0,
      truncated: false,
      attemptedBytes: 0,
      guidanceBytes: 0,
      retrievedContextBytes: 0,
      framingBytes: 0,
    };
  }

  const relevant =
    input.evidence.length > 0
      ? section("Prompt Evidence", input.evidence.map(evidenceBlock).join("\n\n"))
      : undefined;
  const pages = [...new Set(input.evidence.flatMap((evidence) => (evidence.page ? [evidence.page] : [])))];
  const routes = routeRequested
    ? section(
        "Recall Route",
        [
          `- current_project: ${input.matchedProject ? `\`${input.matchedProject}\`` : "unknown_project"}`,
          "- kernel_pages: none",
          `- evidence_pages: ${pages.length > 0 ? pages.map((page) => `\`${page}\``).join(", ") : "none"}`,
          ...(input.temporal ? [`- temporal_query: ${JSON.stringify({
            view: input.temporal.view,
            request_time: input.temporal.request_time,
            ...(input.temporal.world_at !== undefined ? { world_at: input.temporal.world_at } : {}),
            ...(input.temporal.known_at !== undefined ? { known_at: input.temporal.known_at } : {}),
            ...(input.temporal.transition ? { transition: {
              from: input.temporal.transition.from, to: input.temporal.transition.to,
            } } : {}),
          })}`] : []),
        ].join("\n"),
      )
    : undefined;
  const diagnostics = diagnosticSections.length > 0
    ? section(
        "Diagnostics",
        diagnosticSections
          .map((diagnostic) => [
            `- code: ${diagnostic.code}`,
            `- message: ${diagnostic.message.replace(/\s+/g, " ").trim()}`,
            `- recovery: ${diagnostic.recovery.replace(/\s+/g, " ").trim()}`,
          ].join("\n"))
          .join("\n"),
      )
    : undefined;
  const prefix = [
    "## Brain Context",
    ...(input.retrievalLimits ? ["", section("Retrieval limits", input.retrievalLimits)] : []),
    ...(input.includeRoleDisclaimer ? ["", EVIDENCE_ROLE_DISCLAIMER] : []),
    ...(relevant ? ["", relevant] : []),
    ...(diagnostics ? ["", diagnostics] : []),
  ].join("\n");
  const full = `${prefix}${routes ? `\n\n${routes}` : ""}\n`;
  const attemptedBytes = byteLength(full);
  const guidanceBytes = 0;
  const retrievedContextBytes = relevant === undefined ? 0 : byteLength(relevant);
  const framingBytes = attemptedBytes - guidanceBytes - retrievedContextBytes;
  if (attemptedBytes <= input.hardBytes) {
    return {
      markdown: full,
      renderedBytes: attemptedBytes,
      truncated: false,
      attemptedBytes,
      guidanceBytes,
      retrievedContextBytes,
      framingBytes,
    };
  }

  const diagnostic = section(
    "Diagnostics",
    "- code: BRAIN_CONTEXT_TRUNCATED\n- recovery: Repair the compiler-to-envelope byte allowance before retrying.",
  );
  const suffix = `${routes ? `\n\n${routes}` : ""}\n\n[truncated]\n\n${diagnostic}\n`;
  const available = input.hardBytes - byteLength(suffix);
  const markdown =
    available > 0
      ? `${truncateUtf8(prefix, available)}${suffix}`
      : truncateUtf8("## Brain Context\n\n### Diagnostics\n\n- code: BRAIN_CONTEXT_TRUNCATED\n", input.hardBytes);
  return {
    markdown,
    renderedBytes: byteLength(markdown),
    truncated: true,
    attemptedBytes,
    guidanceBytes,
    retrievedContextBytes,
    framingBytes,
  };
}

function oneLine(value: string): string {
  return value.replace(/\s+/g, " ").trim();
}

export function renderDegradedBrainContext(
  diagnostic: BrainContextDiagnostic,
  brainRoot?: string,
  hardBytes = 24_576,
  mode: "bootstrap" | "recall" = "bootstrap",
): BrainContextRender {
  const lines = [
    `## Brain ${mode === "bootstrap" ? "Bootstrap" : "Recall"} Diagnostic`,
    "",
    "- status: degraded",
    `- code: ${diagnostic.code}`,
    ...(brainRoot ? [`- brain_root: ${oneLine(brainRoot)}`] : []),
    `- message: ${oneLine(diagnostic.message)}`,
    `- recovery: ${oneLine(diagnostic.recovery)}`,
    "",
  ];
  const full = lines.join("\n");
  const markdown = hardBytes <= 0 ? "" : byteLength(full) <= hardBytes ? full : `${truncateUtf8(full, hardBytes - 1)}\n`;
  return { markdown, renderedBytes: byteLength(markdown), truncated: markdown !== full };
}

